export function PermissionMatrix({
  highlightRole = "{{highlightRole}}",
  accent = "{{accent}}",
  showLegend = {{showLegend}},
  matrixName = "{{matrixName}}",
}) {
  const roles = ["viewer", "editor", "admin"];
  const rows = [
    { label: "View", grants: { viewer: true, editor: true, admin: true } },
    { label: "Edit", grants: { viewer: false, editor: true, admin: true } },
    { label: "Delete", grants: { viewer: false, editor: false, admin: true } },
  ];
  const cell = (role) => ({ padding: "6px 4px", borderBottom: "1px solid #24143014", fontSize: 11, background: role === highlightRole ? accent : "transparent", borderRadius: role === highlightRole ? 4 : 0 });
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 10px", fontWeight: 700 }}>{matrixName}</p>
      <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "center" }}>
        <tbody>
          <tr><th></th>{roles.map((r) => <th key={r} style={cell(r)}>{r[0].toUpperCase() + r.slice(1)}</th>)}</tr>
          {rows.map((row) => (
            <tr key={row.label}>
              <td style={{ textAlign: "left", padding: "6px 4px", borderBottom: "1px solid #24143014", fontSize: 11 }}>{row.label}</td>
              {roles.map((r) => <td key={r} style={cell(r)}>{row.grants[r] ? "\u2713" : "\u2014"}</td>)}
            </tr>
          ))}
        </tbody>
      </table>
      {showLegend && <p style={{ margin: "10px 0 0", fontSize: 10, color: "#24143099" }}>&#10003; allowed &nbsp; &mdash; not allowed</p>}
    </div>
  );
}
